const mongoose = require("mongoose");

/**
 * Branch Mongoose Schema
 * Contains ONLY the required fields:
 * - _id (Native ObjectId auto-generated by MongoDB)
 * - name (Unique String)
 * - code (Unique String)
 * - address (String)
 * - branchType (String)
 * - weeklyOffDays (Array of Strings)
 * - createdAt (Date)
 * - updatedAt (Date)
 */
const branchSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: [true, "Branch name is required"],
      unique: true,
      trim: true,
    },
    code: {
      type: String,
      required: [true, "Branch code is required"],
      unique: true,
      trim: true,
      uppercase: true,
    },
    address: {
      type: String,
      trim: true,
      default: "",
    },
    branchType: {
      type: String,
      trim: true,
      default: "retail",
    },
    weeklyOffDays: {
      type: [String],
      default: [],
    },
  },
  {
    timestamps: true,
    versionKey: false,
    strict: true,
    toJSON: {
      virtuals: false,
      transform: (doc, ret) => {
        return {
          _id: ret._id,
          name: ret.name,
          code: ret.code,
          address: ret.address || "",
          branchType: ret.branchType || "retail",
          weeklyOffDays: ret.weeklyOffDays || [],
          createdAt: ret.createdAt,
          updatedAt: ret.updatedAt,
        };
      },
    },
  }
);


branchSchema.statics.findAll = async function () {
  return this.find({}).sort({ name: 1 });
};

branchSchema.statics.findByName = async function (name, excludeId = null) {
  if (!name || typeof name !== "string") return null;
  const query = { name: new RegExp('^' + name.trim() + '$', "i") };
  if (excludeId && mongoose.Types.ObjectId.isValid(excludeId)) {
    query._id = { $ne: new mongoose.Types.ObjectId(excludeId) };
  }
  return this.findOne(query);
};

branchSchema.statics.findByCode = async function (code, excludeId = null) {
  if (!code || typeof code !== "string") return null;
  const query = { code: new RegExp('^' + code.trim() + '$', "i") };
  if (excludeId && mongoose.Types.ObjectId.isValid(excludeId)) {
    query._id = { $ne: new mongoose.Types.ObjectId(excludeId) };
  }
  return this.findOne(query);
};

branchSchema.statics.create = async function (branchData) {
  const data = { ...branchData };
  delete data._id;
  delete data.id;
  const branch = new this(data);
  await branch.save();
  return branch;
};

branchSchema.statics.update = async function (id, branchData) {
  if (!id || !mongoose.Types.ObjectId.isValid(id)) return null;
  const data = { ...branchData };
  delete data._id;
  delete data.id;
  return this.findByIdAndUpdate(id, { $set: data }, { new: true, runValidators: true });
};

branchSchema.statics.delete = async function (id) {
  if (!id || !mongoose.Types.ObjectId.isValid(id)) return null;
  return this.findByIdAndDelete(id);
};

const Branch = mongoose.models.Branch || mongoose.model("Branch", branchSchema, "branches");

if (typeof branchSchema !== "undefined" && typeof Branch !== "undefined" && branchSchema.statics) {
  Object.assign(Branch, branchSchema.statics);
}

module.exports = Branch;
